-- V1: persistence foundation — datasets aggregate root.
--
-- datasets is the aggregate root of the Aegivault domain. Findings,
-- sanitization outputs, policies, and audit entries will reference
-- datasets.id in later migrations; none of those tables are created here.
--
-- Conventions established by this migration (apply to all future migrations):
--   * UUID primary keys, generated by gen_random_uuid() (built into
--     PostgreSQL 13+; no extension required).
--   * snake_case, plural table names; primary key column named "id".
--   * TEXT instead of VARCHAR(n); no arbitrary length limits.
--   * TIMESTAMPTZ for timestamps, stored in UTC.
--   * TEXT + CHECK instead of native enums (extendable via later migrations).
--   * Explicitly named constraints (pk_ / chk_ prefixes) and indexes (idx_).
--   * Foreign keys (from V2 on): explicitly named, ON DELETE RESTRICT by
--     default; cascade only where decided and recorded per migration.

CREATE TABLE datasets (
    id                UUID        NOT NULL DEFAULT gen_random_uuid(),
    name              TEXT        NOT NULL,
    source_type       TEXT        NOT NULL DEFAULT 'CSV',
    original_filename TEXT        NULL,
    row_count         BIGINT      NULL,
    status            TEXT        NOT NULL DEFAULT 'UPLOADED',
    owner_subject     TEXT        NULL,
    created_at        TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at        TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT pk_datasets PRIMARY KEY (id),
    CONSTRAINT chk_datasets_name_not_blank CHECK (char_length(btrim(name)) > 0),
    CONSTRAINT chk_datasets_row_count_non_negative CHECK (row_count IS NULL OR row_count >= 0),
    CONSTRAINT chk_datasets_source_type CHECK (source_type IN ('CSV')),
    CONSTRAINT chk_datasets_status CHECK (status IN ('UPLOADED', 'PROCESSING', 'READY', 'FAILED'))
);

COMMENT ON TABLE datasets IS 'Aggregate root of ingested data; findings, outputs, policies, and audit entries reference datasets.id in later phases.';
COMMENT ON COLUMN datasets.owner_subject IS 'Opaque owner identifier. Nullable until authentication exists; migrates to a users FK in the auth phase.';

-- Per-owner dataset listing ("my datasets").
CREATE INDEX idx_datasets_owner_subject ON datasets (owner_subject);

-- Pipeline listing/polling by processing state.
CREATE INDEX idx_datasets_status ON datasets (status);
